<script>
const items=document.getElementById('receta-items');
if(items){let indice=items.children.length;document.getElementById('agregar-item').addEventListener('click',()=>{if(items.children.length>=20)return;const nuevo=items.firstElementChild.cloneNode(true);nuevo.querySelectorAll('[name]').forEach(el=>{el.name=el.name.replace(/items\[\d+\]/,'items['+indice+']');if(el.tagName==='SELECT')el.selectedIndex=0;else el.value=el.type==='number'?'1':'';});indice++;items.append(nuevo);});items.addEventListener('click',e=>{if(e.target.classList.contains('quitar-item')&&items.children.length>1)e.target.closest('fieldset').remove();});}
const canvas=document.getElementById('firma-canvas');
if(canvas){const ctx=canvas.getContext('2d');let dibujando=false,firmado=false;ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#183047';const punto=e=>{const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];};canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);dibujando=true;ctx.beginPath();ctx.moveTo(...punto(e));});canvas.addEventListener('pointermove',e=>{if(!dibujando)return;ctx.lineTo(...punto(e));ctx.stroke();firmado=true;});['pointerup','pointercancel'].forEach(nombre=>canvas.addEventListener(nombre,()=>dibujando=false));document.getElementById('borrar-firma').addEventListener('click',()=>{ctx.clearRect(0,0,canvas.width,canvas.height);firmado=false;document.getElementById('firma').value='';});document.getElementById('consentimiento-form').addEventListener('submit',e=>{if(!firmado){e.preventDefault();document.getElementById('firma-error').hidden=false;return;}document.getElementById('firma').value=canvas.toDataURL('image/png');});}
</script>
@endpush
